using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using ParallelWorld.Domain.Relationships;
using ParallelWorld.Domain.Social;
using ParallelWorld.Domain.Worlds;
namespace ParallelWorld.Infrastructure.Persistence.Configurations;

public sealed class RelationshipConfiguration : IEntityTypeConfiguration<Relationship>
{
    public void Configure(EntityTypeBuilder<Relationship> b) { b.ToTable("relationships", t => { t.HasCheckConstraint("ck_relationships_distinct_actors", "source_actor_id <> target_actor_id"); foreach (var n in Names) t.HasCheckConstraint($"ck_relationships_{n}", $"{n} BETWEEN 0 AND 100"); }); b.HasKey(x => x.Id).HasName("pk_relationships"); b.Property(x => x.Id).HasColumnName("id"); b.Property(x => x.WorldId).HasColumnName("world_id"); b.Property(x => x.SourceActorId).HasColumnName("source_actor_id"); b.Property(x => x.TargetActorId).HasColumnName("target_actor_id"); MapValues(b); b.Property(x => x.CreatedAt).HasColumnName("created_at"); b.Property(x => x.UpdatedAt).HasColumnName("updated_at"); b.Property(x => x.Version).HasColumnName("version").IsConcurrencyToken(); b.HasAlternateKey(x => new { x.WorldId, x.Id }).HasName("ak_relationships_world_id_id"); b.HasIndex(x => new { x.WorldId, x.SourceActorId, x.TargetActorId }).IsUnique().HasDatabaseName("ux_relationships_world_source_target"); b.HasIndex(x => new { x.WorldId, x.SourceActorId, x.UpdatedAt, x.Id }).IsDescending(false, false, true, true).HasDatabaseName("ix_relationships_world_source_updated_id"); b.HasOne<GameWorld>().WithMany().HasForeignKey(x => x.WorldId).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_relationships_game_worlds_world_id"); b.HasOne<Actor>().WithMany().HasForeignKey(x => new { x.WorldId, x.SourceActorId }).HasPrincipalKey(x => new { x.WorldId, x.Id }).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_relationships_actors_world_source"); b.HasOne<Actor>().WithMany().HasForeignKey(x => new { x.WorldId, x.TargetActorId }).HasPrincipalKey(x => new { x.WorldId, x.Id }).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_relationships_actors_world_target"); }
    internal static readonly string[] Names = ["familiarity", "trust", "respect", "affection", "comfort", "rivalry", "jealousy", "attraction", "commitment"];
    private static void MapValues(EntityTypeBuilder<Relationship> b) { b.Property(x => x.Familiarity).HasColumnName("familiarity"); b.Property(x => x.Trust).HasColumnName("trust"); b.Property(x => x.Respect).HasColumnName("respect"); b.Property(x => x.Affection).HasColumnName("affection"); b.Property(x => x.Comfort).HasColumnName("comfort"); b.Property(x => x.Rivalry).HasColumnName("rivalry"); b.Property(x => x.Jealousy).HasColumnName("jealousy"); b.Property(x => x.Attraction).HasColumnName("attraction"); b.Property(x => x.Commitment).HasColumnName("commitment"); }
}
public sealed class RelationshipEventConfiguration : IEntityTypeConfiguration<RelationshipEvent>
{
    public void Configure(EntityTypeBuilder<RelationshipEvent> b) { b.ToTable("relationship_events", t => { t.HasCheckConstraint("ck_relationship_events_distinct_actors", "source_actor_id <> target_actor_id"); foreach (var n in RelationshipConfiguration.Names) t.HasCheckConstraint($"ck_relationship_events_{n}_delta", $"{n}_delta BETWEEN -30 AND 30"); }); b.HasKey(x => x.Id).HasName("pk_relationship_events"); b.Property(x => x.Id).HasColumnName("id"); b.Property(x => x.WorldId).HasColumnName("world_id"); b.Property(x => x.RelationshipId).HasColumnName("relationship_id"); b.Property(x => x.SourceActorId).HasColumnName("source_actor_id"); b.Property(x => x.TargetActorId).HasColumnName("target_actor_id"); b.Property(x => x.GameplayEventId).HasColumnName("gameplay_event_id"); b.Property(x => x.EventType).HasColumnName("event_type").HasMaxLength(80); MapDeltas(b); b.Property(x => x.BeforeValues).HasColumnName("before_values").HasColumnType("jsonb"); b.Property(x => x.AfterValues).HasColumnName("after_values").HasColumnType("jsonb"); b.Property(x => x.ReasonCode).HasColumnName("reason_code").HasMaxLength(80); b.Property(x => x.OccurredAt).HasColumnName("occurred_at"); b.Property(x => x.OccurredGameDate).HasColumnName("occurred_game_date"); b.Property(x => x.IsQualifiedNegative).HasColumnName("is_qualified_negative"); b.Property(x => x.RuleVersion).HasColumnName("rule_version"); b.Property(x => x.IdempotencyKey).HasColumnName("idempotency_key").HasMaxLength(200); b.HasIndex(x => new { x.WorldId, x.IdempotencyKey }).IsUnique().HasDatabaseName("ux_relationship_events_world_idempotency_key"); b.HasIndex(x => new { x.WorldId, x.GameplayEventId, x.SourceActorId, x.TargetActorId, x.RuleVersion }).IsUnique().HasDatabaseName("ux_relationship_events_source_rule_direction"); b.HasIndex(x => new { x.WorldId, x.SourceActorId, x.TargetActorId, x.OccurredAt, x.Id }).IsDescending(false, false, false, true, true).HasDatabaseName("ix_relationship_events_history"); b.HasIndex(x => new { x.WorldId, x.SourceActorId, x.TargetActorId, x.OccurredGameDate }).HasDatabaseName("ix_relationship_events_game_date"); b.HasOne<Relationship>().WithMany().HasForeignKey(x => new { x.WorldId, x.RelationshipId }).HasPrincipalKey(x => new { x.WorldId, x.Id }).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_relationship_events_relationships_world_relationship"); b.HasOne<GameplayEvent>().WithMany().HasForeignKey(x => new { x.WorldId, x.GameplayEventId }).HasPrincipalKey(x => new { x.WorldId, x.Id }).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_relationship_events_gameplay_events_world_event"); b.HasOne<Actor>().WithMany().HasForeignKey(x => new { x.WorldId, x.SourceActorId }).HasPrincipalKey(x => new { x.WorldId, x.Id }).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_relationship_events_actors_world_source"); b.HasOne<Actor>().WithMany().HasForeignKey(x => new { x.WorldId, x.TargetActorId }).HasPrincipalKey(x => new { x.WorldId, x.Id }).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_relationship_events_actors_world_target"); }
    private static void MapDeltas(EntityTypeBuilder<RelationshipEvent> b) { b.Property(x => x.BaseFamiliarity).HasColumnName("base_familiarity"); b.Property(x => x.BaseTrust).HasColumnName("base_trust"); b.Property(x => x.BaseRespect).HasColumnName("base_respect"); b.Property(x => x.BaseAffection).HasColumnName("base_affection"); b.Property(x => x.BaseComfort).HasColumnName("base_comfort"); b.Property(x => x.BaseRivalry).HasColumnName("base_rivalry"); b.Property(x => x.BaseJealousy).HasColumnName("base_jealousy"); b.Property(x => x.BaseAttraction).HasColumnName("base_attraction"); b.Property(x => x.BaseCommitment).HasColumnName("base_commitment"); b.Property(x => x.FamiliarityDelta).HasColumnName("familiarity_delta"); b.Property(x => x.TrustDelta).HasColumnName("trust_delta"); b.Property(x => x.RespectDelta).HasColumnName("respect_delta"); b.Property(x => x.AffectionDelta).HasColumnName("affection_delta"); b.Property(x => x.ComfortDelta).HasColumnName("comfort_delta"); b.Property(x => x.RivalryDelta).HasColumnName("rivalry_delta"); b.Property(x => x.JealousyDelta).HasColumnName("jealousy_delta"); b.Property(x => x.AttractionDelta).HasColumnName("attraction_delta"); b.Property(x => x.CommitmentDelta).HasColumnName("commitment_delta"); }
}
public sealed class RelationshipDailyChangeLedgerConfiguration : IEntityTypeConfiguration<RelationshipDailyChangeLedger>
{
    public void Configure(EntityTypeBuilder<RelationshipDailyChangeLedger> b) { b.ToTable("relationship_daily_change_ledgers", t => { t.HasCheckConstraint("ck_relationship_daily_ledgers_distinct_actors", "source_actor_id <> target_actor_id"); foreach (var n in RelationshipConfiguration.Names) t.HasCheckConstraint($"ck_relationship_daily_ledgers_{n}", $"{n} BETWEEN 0 AND 20"); }); b.HasKey(x => new { x.WorldId, x.SourceActorId, x.TargetActorId, x.GameDate }).HasName("pk_relationship_daily_change_ledgers"); b.Property(x => x.WorldId).HasColumnName("world_id"); b.Property(x => x.SourceActorId).HasColumnName("source_actor_id"); b.Property(x => x.TargetActorId).HasColumnName("target_actor_id"); b.Property(x => x.GameDate).HasColumnName("game_date"); b.Property(x => x.Familiarity).HasColumnName("familiarity"); b.Property(x => x.Trust).HasColumnName("trust"); b.Property(x => x.Respect).HasColumnName("respect"); b.Property(x => x.Affection).HasColumnName("affection"); b.Property(x => x.Comfort).HasColumnName("comfort"); b.Property(x => x.Rivalry).HasColumnName("rivalry"); b.Property(x => x.Jealousy).HasColumnName("jealousy"); b.Property(x => x.Attraction).HasColumnName("attraction"); b.Property(x => x.Commitment).HasColumnName("commitment"); b.Property(x => x.SevereBypassUsed).HasColumnName("severe_bypass_used"); b.Property(x => x.UpdatedAt).HasColumnName("updated_at"); b.Property(x => x.Version).HasColumnName("version").IsConcurrencyToken(); b.HasOne<Actor>().WithMany().HasForeignKey(x => new { x.WorldId, x.SourceActorId }).HasPrincipalKey(x => new { x.WorldId, x.Id }).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_relationship_daily_ledgers_actors_world_source"); b.HasOne<Actor>().WithMany().HasForeignKey(x => new { x.WorldId, x.TargetActorId }).HasPrincipalKey(x => new { x.WorldId, x.Id }).OnDelete(DeleteBehavior.Restrict).HasConstraintName("fk_relationship_daily_ledgers_actors_world_target"); }
}
